def prepare_dataset():
    print("=" * 55)
    print("  Preparing sample fallback product dataset")
    print("=" * 55)
    df = pd.DataFrame(SAMPLE_PRODUCTS)
    os.makedirs("./data", exist_ok=True)
    output_path = "./data/abo_products.csv"
    df.to_csv(output_path, index=False)
    print(f"\n✅ Dataset ready: {len(df)} products saved to {output_path}")
    print("\n✅ Now run: python scripts/index_catalog.py")
    return df


if __name__ == "__main__":
    prepare_dataset()
